<template>
  <div
    v-if="hasSize"
    class="unprocessed-page-overlay"
    :style="overlayStyle"
    data-testid="unprocessed-page-overlay"
  >
    <span class="unprocessed-page-overlay__badge">
      <Icon icon="mdi:lock-outline" width="14" height="14" />
      {{ $t('unprocessed_page_read_only') }}
    </span>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';

/**
 * Marks a document page the backend never OCR'd — see
 * documentUtil.isProcessedPage. Render it as a sibling of the
 * page image, inside the same positioned container.
 *
 * Sizing, either:
 *  - `width` (the same value bound to the image) plus `height` in px, or
 *    `aspectRatio` when the image height is only known from its ratio; or
 *  - `fill`, to cover the nearest positioned ancestor, for a page image laid
 *    out in normal flow rather than absolutely positioned.
 */
export default defineComponent({
  name: 'UnprocessedPageOverlay',
  props: {
    width: {
      type: Number,
      default: 0,
    },
    height: {
      type: Number,
      default: 0,
    },
    aspectRatio: {
      type: Number,
      default: 0,
    },
    offsetLeft: {
      type: Number,
      default: 0,
    },
    // Cover the positioned parent instead of being sized in px.
    fill: {
      type: Boolean,
      default: false,
    },
  },
  computed: {
    // The image size arrives a tick (or an async load) after the page data, so
    // render nothing until it does. Without this the box would be 0px wide
    // with an auto height and the badge would float loose over the viewer.
    hasSize(): boolean {
      if (this.fill) {
        return true;
      }
      return this.width > 0 && (this.height > 0 || this.aspectRatio > 0);
    },
    overlayStyle(): Record<string, string> {
      if (this.fill) {
        return { inset: '0' };
      }
      const style: Record<string, string> = { width: this.width + 'px' };
      if (this.offsetLeft) {
        style.marginLeft = this.offsetLeft + 'px';
      }
      if (this.height) {
        style.height = this.height + 'px';
      } else {
        style.aspectRatio = String(this.aspectRatio);
      }
      return style;
    },
  },
});
</script>

